B=(1,1);
C=(1,-1);
D=(-1,-1);
E=(-1,-.577);
F=(-1,.577);
M=(-1,0);
draw(circle(O,1.155));
draw(A--B);
draw(B--C);
draw(C--D);
draw(D--A);
draw(F--O);
